// Polar Clock — Animation, route: jsx
// Source: polar-clock
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';

const MAX_SIZE = 520;
const MARGIN = 18;
const TAU = 2 * Math.PI;

type Field = {
  name: string;
  cycle: d3.TimeInterval;
  format: (date: Date) => string;
  suffix: string;
};

// Innermost ring first. `cycle` is the period one full sweep covers, so the arc
// for the seconds ring measures how far the current minute has run.
const FIELDS: Field[] = [
  { name: 'month of the year', cycle: d3.timeYear, format: d3.timeFormat('%b'), suffix: '' },
  { name: 'day of the month', cycle: d3.timeMonth, format: d3.timeFormat('%-d'), suffix: 'd' },
  { name: 'hour of the day', cycle: d3.timeDay, format: d3.timeFormat('%-H'), suffix: 'h' },
  { name: 'minute of the hour', cycle: d3.timeHour, format: d3.timeFormat('%-M'), suffix: 'm' },
  { name: 'second of the minute', cycle: d3.timeMinute, format: d3.timeFormat('%-S'), suffix: 's' }
];

const formatTime = d3.timeFormat('%H:%M:%S');
const formatDate = d3.timeFormat('%a %d %b %Y');

// Measured off the real interval boundaries so months, leap years and DST all land right.
function progress(cycle: d3.TimeInterval, now: Date): number {
  const start = cycle(now);
  const span = cycle.offset(start, 1).getTime() - start.getTime();
  return (now.getTime() - start.getTime()) / span;
}

export default function PolarClock({ width }: { width: number }) {
  const height = Math.min(width, MAX_SIZE);
  const radius = Math.min(width, height) / 2 - MARGIN;
  const step = radius * 0.14;
  const bandWidth = Math.min(step * 0.34, 15);

  const [now, setNow] = useState<Date>(() => new Date());

  // It is a clock, so the wall clock is the data. One rAF loop, cancelled on unmount.
  useEffect(() => {
    let frame = 0;
    const tick = () => {
      setNow(new Date());
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, []);

  const arc = useMemo(
    () => d3.arc<d3.DefaultArcObject>().cornerRadius(bandWidth),
    [bandWidth]
  );

  if (width === 0) return null;

  const centerSize = Math.max(11, radius * 0.1);
  const showTips = bandWidth >= 8;

  // Recomputed every frame: the arcs are five cheap paths, so React can own them.
  const rings = FIELDS.map((field, i) => {
    const r = radius * 0.34 + i * step;
    const fraction = progress(field.cycle, now);
    const endAngle = Math.max(fraction, 0.001) * TAU;
    const label = field.format(now) + field.suffix;

    // Pull the readout back inside the arc once the sweep is long enough to hold it.
    const fitsInside = endAngle * r > 44;
    const [labelX, labelY] = d3.pointRadial(endAngle + (fitsInside ? -22 : 18) / r, r);

    return {
      key: field.name,
      name: field.name,
      d: arc({ innerRadius: r - bandWidth, outerRadius: r + bandWidth, startAngle: 0, endAngle }) ?? '',
      color: d3.interpolateRainbow(fraction),
      r,
      label,
      labelX,
      labelY,
      fitsInside
    };
  });

  return (
    <svg
      viewBox={`${-width / 2} ${-height / 2} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`Polar clock: concentric arcs sweeping the ${FIELDS.map((f) => f.name).join(', ')}. Currently ${formatTime(now)} on ${formatDate(now)}`}
    >
      {rings.map((ring) => (
        <circle key={ring.key} r={ring.r} fill="none" stroke="var(--line)" strokeWidth={bandWidth * 2} />
      ))}

      {rings.map((ring) => (
        <path key={ring.key} d={ring.d} fill={ring.color} />
      ))}

      {showTips && (
        <g textAnchor="middle" fontSize={bandWidth * 1.15} fontWeight={600}>
          {rings.map((ring) => (
            <text
              key={ring.key}
              x={ring.labelX}
              y={ring.labelY}
              dy="0.35em"
              fill={ring.fitsInside ? 'var(--bg)' : 'var(--muted)'}
            >
              {ring.label}
            </text>
          ))}
        </g>
      )}

      <g textAnchor="middle" fill="var(--text)">
        <text
          y={-centerSize * 0.1}
          fontSize={centerSize}
          fontWeight={600}
          style={{ fontVariantNumeric: 'tabular-nums' }}
        >
          {formatTime(now)}
        </text>
        <text y={centerSize * 1.1} fontSize={centerSize * 0.62} fill="var(--muted)">
          {formatDate(now)}
        </text>
      </g>
    </svg>
  );
}
